WITH ss AS ( SELECT ss_cdemo_sk, SUM(ss_net_paid) AS total_sales, SUM(ss_quantity) AS total_quantity, SUM(ss_net_profit) AS total_profit FROM store_sales GROUP BY ss_cdemo_sk ), sr AS ( SELECT sr_cdemo_sk, SUM(sr_net_loss) AS total_store_return_loss, SUM(sr_return_quantity) AS total_store_return_qty FROM store_returns GROUP BY sr_cdemo_sk ), cr AS ( SELECT cr_refunded_cdemo_sk, cr_call_center_sk, SUM(cr_net_loss) AS total_catalog_return_loss, SUM(cr_return_quantity) AS total_catalog_return_qty FROM catalog_returns GROUP BY cr_refunded_cdemo_sk, cr_call_center_sk ), cd AS ( SELECT cd_demo_sk, cd_gender, cd_credit_rating FROM customer_demographics WHERE cd_credit_rating = 'A' ) SELECT cc.cc_call_center_id, cc.cc_name, cd.cd_gender, SUM(ss.total_sales) AS total_sales, SUM(ss.total_quantity) AS total_quantity, SUM(ss.total_profit) AS total_profit, SUM(sr.total_store_return_loss) AS total_store_return_loss, SUM(sr.total_store_return_qty) AS total_store_return_qty, SUM(cr.total_catalog_return_loss) AS total_catalog_return_loss, SUM(cr.total_catalog_return_qty) AS total_catalog_return_qty, (SUM(ss.total_profit) - COALESCE(SUM(sr.total_store_return_loss), 0) - COALESCE(SUM(cr.total_catalog_return_loss), 0)) AS net_profit FROM cd LEFT JOIN ss ON ss.ss_cdemo_sk = cd.cd_demo_sk LEFT JOIN sr ON sr.sr_cdemo_sk = cd.cd_demo_sk LEFT JOIN cr ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk JOIN call_center cc ON cc.cc_call_center_sk = cr.cr_call_center_sk WHERE cc.cc_gmt_offset = -5.00 AND cc.cc_open_date_sk > 2450900 GROUP BY cc.cc_call_center_id, cc.cc_name, cd.cd_gender ORDER BY net_profit DESC LIMIT 100
